import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import path from 'node:path';
import { parse } from 'yaml';

// Invokes the external Builder's actual build/deploy entrypoint. No Result,
// Runtime evidence or model responses are generated by this test driver.
export function liveTaskBuilder({directory, port, python, modelConfig}) {
  const root = process.env.MIGRATION_LIVE_BUILDER_ROOT;
  const hostPython = process.env.MIGRATION_LIVE_BUILDER_PYTHON;
  assert(root && hostPython, 'Configure real Builder root and host Python');
  const baseUrl = `http://127.0.0.1:${port}/oj/`;
  const trust = [{reference:'real-builder', label:'真实 Finance Solution Builder', baseUrlPrefix:baseUrl, credentialEnv:'LIVE_BUILDER_TOKEN'}];
  const builds=[];
  let active;
  async function close() {
    if (!active) return;
    await writeFile(path.join(active.state,'stop'),'stop');
    await Promise.race([active.exit, new Promise((_,reject)=>setTimeout(()=>reject(new Error('Builder cleanup timed out')),30000).unref())]);
    active.log.end(); active=null;
  }
  async function bind(page) {
    await close();
    const round=path.join(directory,'builder-'+builds.length);
    await mkdir(round,{recursive:true});
    const download=page.waitForEvent('download');
    await page.getByRole('button',{name:'生成并下载 Builder 需求',exact:true}).click();
    await (await download).saveAs(path.join(round,'requirements.yaml'));
    const requirements=parse(await readFile(path.join(round,'requirements.yaml'),'utf8'));
    await writeFile(path.join(round,'requirements.json'),JSON.stringify(requirements));
    const source=page.waitForEvent('download');
    await page.getByRole('button',{name:'下载绑定的候选源码',exact:true}).click();
    await (await source).saveAs(path.join(round,'candidate.zip'));
    const state=path.join(round,'state'), log=createWriteStream(path.join(round,'builder.log'));
    const child=spawn(hostPython,[path.join(root,'engineering/build_migration_task.py'),
      '--requirements',path.join(round,'requirements.json'),'--source',path.join(round,'candidate.zip'),
      '--state-root',state,'--python',python,'--model-config',modelConfig,'--port',String(port)],
      {cwd:root,windowsHide:true,env:{...process.env,PYTHONUTF8:'1',PYTHONUNBUFFERED:'1'},stdio:['ignore','pipe','pipe']});
    child.stdout.pipe(log); child.stderr.pipe(log);
    const exit=new Promise(resolve=>child.once('exit',resolve));
    active={state,log,child,exit};
    const deadline=Date.now()+15*60*1000;
    let info;
    while(Date.now()<deadline) {
      assert.equal(child.exitCode,null,'Real Builder exited; inspect retained builder.log');
      info=await readFile(path.join(state,'connection-info.json'),'utf8').then(JSON.parse).catch(()=>null);
      if(info)break;
      await new Promise(resolve=>setTimeout(resolve,1500));
    }
    assert.equal(info?.status,'READY','Real Builder build exceeded deadline');
    assert.equal(info.baseUrl,baseUrl);
    process.env.LIVE_BUILDER_TOKEN=info.token;
    const result=JSON.parse(await readFile(path.join(state,'result.json'),'utf8'));
    assert.equal(result.status,'SUCCEEDED');
    builds.push({buildId:result.buildId,requestId:result.requestId,deploymentId:result.launcher.deploymentId,
      artifactSha256:result.launcher.artifactSha256,resultDigest:result.resultDigest,candidateId:requirements.source.assetId});
    await page.getByLabel('导入 Builder Result JSON',{exact:true}).setInputFiles(path.join(state,'result.json'));
    await page.getByLabel('Builder 交付信任引用',{exact:true}).selectOption('real-builder');
    const accepted=page.waitForResponse(r=>r.url().endsWith('/runtime-deliveries')&&r.request().method()==='POST',{timeout:900000});
    await page.getByRole('button',{name:'验证并绑定 Builder 交付',exact:true}).click();
    const response=await accepted;
    assert.equal(response.status(),200,await response.text());
    const capabilities=await fetch(baseUrl+'v1/runtime-capabilities',{headers:{authorization:'Bearer '+info.token}}).then(r=>r.json());
    assert(capabilities.features.multiSkill);
    return capabilities;
  }
  return {baseUrl,trust,builds,bind,close};
}
